script:
(function () {
  'use strict';
  // Balance transfer vs staying put. Each month: interest = balance x APR / 12 (rounded to the
  // cent), then the fixed monthly payment (capped at what is owed). The transfer starts from
  // balance + fee when the fee is added to the card (fee = max(fee % x balance, minimum fee); no fee at 0%),
  // runs at the intro APR for the intro months, then at the post-intro APR. Total cost = interest
  // + fee. Payment to clear within the intro = level payment on (balance + fee) over the intro
  // months at the intro APR: B / n at 0%, otherwise rB / (1 - (1 + r)^-n), rounded up to the cent.
  // Verified (scratchpad tests/b3debt/bt.test.js):
  //   staying put on $6,000 at 22.99% paying $300: 26 months, $1,638.67 interest, within $1 of the
  //   closed-form annuity (n = -ln(1 - rB/P) / ln(1 + r) = 25.46 months, $1,637.98);
  //   default transfer ($6,000, 3% fee = $180, 0% for 18 months, $300/month): $780 left when the
  //   intro ends (6,180 - 18 x 300), cleared in month 21 with interest matching a hand-run of the
  //   last three months at 24.99%;
  //   payment to clear in the intro = $343.34 (6,180 / 18 rounded up) and at 5% intro APR equals
  //   the closed-form level payment; a $100 balance hits the $5 minimum fee;
  //   a payment below the monthly interest reports "not paid off" instead of looping.
  var MAX_MONTHS = 600;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });

  function cents(x) { return Math.round(x * 100) / 100; }
  function num(id) { var v = document.getElementById(id).value; return v.trim() === '' ? NaN : parseFloat(v); }
  function set(id, text) { document.getElementById(id).textContent = text; }

  // aprFor(month) returns the APR (decimal) charged in that month (1-based).
  function simulate(balance, payment, aprFor) {
    var bal = balance, interest = 0, paid = 0, rows = [];
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var i = cents(bal * aprFor(m) / 12);
      bal += i; interest += i;
      var pay = Math.min(payment, bal);
      bal = cents(bal - pay); paid += pay;
      rows.push({ interest: i, balance: bal });
      if (bal <= 0.005) return { paidOff: true, months: m, interest: interest, paid: paid, rows: rows };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: interest, paid: paid, rows: rows };
  }

  function levelPayment(principal, apr, n) {
    if (n <= 0) return NaN;
    var r = apr / 12;
    var p = r === 0 ? principal / n : principal * r / (1 - Math.pow(1 + r, -n));
    return Math.ceil(p * 100 - 1e-6) / 100;
  }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
    body.appendChild(tr);
  }

  function clearResults() {
    ['btSave', 'btNeeded', 'btLeft', 'btFeeAmt'].forEach(function (id) { set(id, '–'); });
    set('btNeededNote', '');
    set('btSaveLabel', 'You save by transferring');
    document.getElementById('btNote').hidden = true;
    clearBody('btCompare'); clearBody('btSchedule');
  }

  function update() {
    var balance = num('btBalance'), curApr = num('btCurApr'), payment = num('btPayment'),
        promoApr = num('btPromoApr'), promoMonths = num('btPromoMonths'), feePct = num('btFee'),
        postApr = num('btPostApr'), minFee = num('btMinFee');
    if (isNaN(minFee)) minFee = 0;
    var feeAdded = document.getElementById('btFeeAdded').checked;
    var error = document.getElementById('btError');
    var bad = [balance, curApr, payment, promoApr, promoMonths, feePct, postApr].some(isNaN) ||
      balance <= 0 || balance > 1e8 || payment <= 0 || curApr < 0 || curApr > 100 || promoApr < 0 || promoApr > 100 ||
      postApr < 0 || postApr > 100 || promoMonths < 0 || promoMonths > 60 || promoMonths !== Math.floor(promoMonths) ||
      feePct < 0 || feePct > 25 || minFee < 0;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a balance and payment above $0, APRs from 0 to 100%, an intro period of 0 to 60 whole months and a fee from 0 to 25%.';
      clearResults();
      return;
    }
    error.textContent = '';
    var fee = feePct > 0 ? cents(Math.max(balance * feePct / 100, minFee)) : 0;
    var startBal = balance + (feeAdded ? fee : 0);
    var stay = simulate(balance, payment, function () { return curApr / 100; });
    var move = simulate(startBal, payment, function (m) { return (m <= promoMonths ? promoApr : postApr) / 100; });
    var moveCost = move.interest + fee, stayCost = stay.interest;
    var movePaid = move.paid + (feeAdded ? 0 : fee);

    set('btFeeAmt', money.format(fee));
    if (promoMonths > 0) {
      var need = levelPayment(startBal, promoApr / 100, promoMonths);
      set('btNeeded', money.format(need) + '/mo');
      set('btNeededNote', need <= payment + 0.005 ? 'Your payment is enough to clear it before the higher rate starts.'
        : money.format(cents(need - payment)) + ' a month more than you plan to pay.');
      var left = move.paidOff && move.months <= promoMonths ? 0 : move.rows[promoMonths - 1].balance;
      set('btLeft', money.format(left));
    } else {
      set('btNeeded', '–'); set('btNeededNote', 'This offer has no intro period.');
      set('btLeft', '–');
    }

    var note = document.getElementById('btNote');
    if (move.paidOff && stay.paidOff) {
      var save = stayCost - moveCost;
      set('btSaveLabel', save >= 0 ? 'You save by transferring' : 'Transferring costs you more by');
      set('btSave', money.format(Math.abs(save)));
      note.hidden = true;
    } else {
      set('btSaveLabel', 'You save by transferring');
      set('btSave', '–');
      note.hidden = false;
      note.textContent = !stay.paidOff && !move.paidOff
        ? 'Your payment does not keep up with the interest on either card, so the balance is never paid off. Try a larger monthly payment.'
        : (!stay.paidOff
          ? 'At this payment the balance on your current card is never paid off, so any transfer that clears it is the better choice. Raise the payment to compare exact costs.'
          : 'At this payment the transferred balance is never paid off once the intro rate ends. Raise the payment to compare exact costs.');
    }

    var compare = clearBody('btCompare');
    [['Transfer to the new card', move, move.interest, fee, moveCost, movePaid],
     ['Keep it on your current card', stay, stay.interest, 0, stayCost, stay.paid]].forEach(function (p) {
      var s = p[1];
      addRow(compare, [p[0], s.paidOff ? duration(s.months) : 'Over 50 years',
        s.paidOff ? money.format(p[2]) : '–', money.format(p[3]), s.paidOff ? money.format(p[4]) : '–', s.paidOff ? money.format(p[5]) : '–']);
    });

    var sched = clearBody('btSchedule');
    var count = Math.min(Math.max(move.rows.length, stay.rows.length), 360);
    for (var m = 0; m < count; m++) {
      var a = move.rows[m], b = stay.rows[m];
      addRow(sched, [String(m + 1) + (promoMonths > 0 && m + 1 === promoMonths ? ' (intro ends)' : ''),
        a ? money.format(a.interest) : '–', a ? money.format(a.balance) : money.format(0),
        b ? money.format(b.interest) : '–', b ? money.format(b.balance) : money.format(0)]);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('btForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
